BEGIN;
CREATE SCHEMA IF NOT EXISTS orcafacil;
CREATE TABLE IF NOT EXISTS orcafacil.omnichannel_channels (id uuid PRIMARY KEY,account_id uuid NULL,type varchar(32) NOT NULL,status varchar(24) NOT NULL DEFAULT 'NotConfigured',name varchar(120) NOT NULL,is_global boolean NOT NULL DEFAULT false,is_enabled boolean NOT NULL DEFAULT false,last_health_check_at timestamptz NULL,last_failure text NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NULL,is_deleted boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_omnichannel_channel_scope_type ON orcafacil.omnichannel_channels(COALESCE(account_id,'00000000-0000-0000-0000-000000000000'::uuid),type) WHERE NOT is_deleted;
CREATE TABLE IF NOT EXISTS orcafacil.omnichannel_conversations (id uuid PRIMARY KEY,account_id uuid NOT NULL,channel_id uuid NOT NULL REFERENCES orcafacil.omnichannel_channels(id),status varchar(24) NOT NULL DEFAULT 'New',client_id uuid NULL,lead_id uuid NULL,partner_id uuid NULL,ticket_id uuid NULL,assigned_user_id uuid NULL,queue_id uuid NULL,subject varchar(200) NOT NULL DEFAULT '',priority varchar(24) NOT NULL DEFAULT 'Normal',first_response_due_at timestamptz NULL,resolution_due_at timestamptz NULL,last_message_at timestamptz NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NULL,is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_omnichannel_inbox ON orcafacil.omnichannel_conversations(account_id,status,last_message_at DESC) WHERE NOT is_deleted;
CREATE TABLE IF NOT EXISTS orcafacil.omnichannel_conversation_participants (id uuid PRIMARY KEY,account_id uuid NOT NULL,conversation_id uuid NOT NULL REFERENCES orcafacil.omnichannel_conversations(id),type varchar(32) NOT NULL,reference_id uuid NULL,display_name varchar(160) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NULL,is_deleted boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.omnichannel_messages (id uuid PRIMARY KEY,account_id uuid NOT NULL,conversation_id uuid NOT NULL REFERENCES orcafacil.omnichannel_conversations(id),channel_id uuid NOT NULL,sender_type varchar(32) NOT NULL,sender_user_id uuid NULL,sender_display_name varchar(160) NOT NULL,direction varchar(16) NOT NULL,type varchar(24) NOT NULL,status varchar(24) NOT NULL,content varchar(20000) NOT NULL,external_message_id varchar(255) NULL,sent_at timestamptz NULL,delivered_at timestamptz NULL,read_at timestamptz NULL,failed_at timestamptz NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NULL,is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_omnichannel_message_timeline ON orcafacil.omnichannel_messages(account_id,conversation_id,created_at) WHERE NOT is_deleted;
CREATE UNIQUE INDEX IF NOT EXISTS ux_omnichannel_external_message ON orcafacil.omnichannel_messages(account_id,channel_id,external_message_id) WHERE external_message_id IS NOT NULL AND NOT is_deleted;
CREATE TABLE IF NOT EXISTS orcafacil.omnichannel_message_delivery_logs (id uuid PRIMARY KEY,account_id uuid NOT NULL,message_id uuid NOT NULL,event_type varchar(40) NOT NULL,provider_reference varchar(255) NULL,sanitized_error text NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NULL,is_deleted boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.omnichannel_web_chat_sessions (id uuid PRIMARY KEY,account_id uuid NOT NULL,conversation_id uuid NOT NULL,token_hash varchar(64) NOT NULL UNIQUE,visitor_name varchar(160) NOT NULL,visitor_email varchar(254) NOT NULL,expires_at timestamptz NOT NULL,consent_accepted boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NULL,is_deleted boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.omnichannel_inbound_email_accounts (id uuid PRIMARY KEY,account_id uuid NOT NULL,address varchar(254) NOT NULL,mode varchar(24) NOT NULL DEFAULT 'Manual',has_protected_credential boolean NOT NULL DEFAULT false,is_enabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NULL,is_deleted boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.omnichannel_opt_out_events (id uuid PRIMARY KEY,account_id uuid NOT NULL,identity_hash varchar(64) NOT NULL,channel varchar(32) NOT NULL,scope varchar(24) NOT NULL DEFAULT 'Commercial',opted_out_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NULL,is_deleted boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.omnichannel_sla_events (id uuid PRIMARY KEY,account_id uuid NOT NULL,conversation_id uuid NOT NULL,type varchar(40) NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NULL,is_deleted boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_omnichannel_sla_once ON orcafacil.omnichannel_sla_events(conversation_id,type) WHERE NOT is_deleted;
CREATE TABLE IF NOT EXISTS orcafacil.omnichannel_csat_responses (id uuid PRIMARY KEY,account_id uuid NOT NULL,conversation_id uuid NOT NULL,request_token_hash varchar(64) NOT NULL,rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),comment varchar(2000) NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NULL,is_deleted boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_omnichannel_csat_once ON orcafacil.omnichannel_csat_responses(conversation_id) WHERE NOT is_deleted;
DO $omni$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['omnichannel_channel_accounts','omnichannel_message_attachments','omnichannel_message_events','omnichannel_inbox_assignments','omnichannel_inbox_queues','omnichannel_queue_members','omnichannel_contact_identities','omnichannel_contact_links','omnichannel_channel_health_checks','omnichannel_automation_rules','omnichannel_routing_rules','omnichannel_sla_policies','omnichannel_web_chat_widgets','omnichannel_inbound_email_messages','omnichannel_whatsapp_accounts','omnichannel_whatsapp_templates','omnichannel_whatsapp_delivery_logs','omnichannel_conversation_tags','omnichannel_conversation_tag_links','omnichannel_csat_requests','omnichannel_operational_snapshots'] LOOP EXECUTE format('CREATE TABLE IF NOT EXISTS orcafacil.%I (id uuid PRIMARY KEY, account_id uuid NOT NULL, data_json jsonb NOT NULL DEFAULT ''{}''::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false)',t); EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON orcafacil.%I(account_id,created_at)', 'ix_'||t||'_account',t); END LOOP; END $omni$;
COMMIT;
